-- supabase/seed-vi-all.sql
-- COMBINED Vietnamese UI seed = migrations 0031 through 0050 in one file.
-- Paste this WHOLE file into the Supabase SQL Editor and Run once.
-- Every statement is idempotent (ON CONFLICT DO NOTHING) so re-running is safe.
-- Requires migration 0030 (ui_translations table) to already exist.


-- ============================================================
-- >>> supabase/migrations/0031_seed_ui_translations_vi.sql
-- ============================================================
-- supabase/migrations/0031_seed_ui_translations_vi.sql
-- Phase 1: Vietnamese (vi) DRAFT seed for the UI dictionary.
--
-- Machine/assistant-drafted with Vietnamese Protestant/pastoral terminology
-- (e.g. Tĩnh nguyện = devotional, Cầu thay = intercession, được nhậm = answered
-- prayer, Sự mặc khải = revelations, Lời chứng = testimonies, Dâng hiến = giving).
-- Every row is reviewed=false — a native Vietnamese speaker/pastor should review
-- and flip reviewed=true (or edit) via the Language Manager (Phase 3.5).
--
-- ON CONFLICT DO NOTHING: re-running never overwrites a human-reviewed value.
-- Mirrors DEFAULT_TRANSLATIONS in src/lib/i18n.ts. Run in the Supabase SQL Editor.

