('vi','landing','prob2Desc','Các hội thánh chật vật trong việc giao tiếp, phát sóng và môn đồ hóa ở quy mô lớn với những công cụ rời rạc không được thiết kế cho cộng đồng đức tin.',false),
('vi','landing','prob3Title','Việc chăm sóc thuộc linh khó tiếp cận',false),
('vi','landing','prob3Desc','Tư vấn, trách nhiệm cầu nguyện và cộng đồng bị phân tán trên nhiều ứng dụng và nhóm WhatsApp. ReKindle hợp nhất tất cả.',false),
('vi','landing','featuresEyebrow','Mọi thứ bạn cần',false),
('vi','landing','featuresTitle','Được xây dựng cho mọi khía cạnh đời sống đức tin của bạn',false),
('vi','landing','featuresSubtitle','Từ đời sống tĩnh nguyện cá nhân đến phát sóng quy mô mục vụ — ReKindle bao trọn cả hành trình.',false),
('vi','landing','feat1Title','Tĩnh nguyện hằng ngày',false),
('vi','landing','feat1Desc','Các loạt bài tĩnh nguyện phong phú, được tuyển chọn với Kinh Thánh, suy ngẫm, bước hành động và cầu nguyện hướng dẫn — một lời tươi mới cho mỗi ngày trên hành trình của bạn.',false),
('vi','landing','feat2Title','Tĩnh nguyện bằng âm thanh',false),
('vi','landing','feat2Desc','Nghe thay vì đọc. Mỗi bài tĩnh nguyện được tự động thuật lại với nhạc nền nhẹ nhàng, để bạn có thể tăng trưởng khi di chuyển, ở phòng tập, hay trước khi ngủ.',false),
('vi','landing','feat3Title','Truy cập ngoại tuyến',false),
('vi','landing','feat3Desc','Tải các bài tĩnh nguyện và đọc hoặc nghe ở bất cứ đâu — không cần tín hiệu. Tiến độ của bạn tự động đồng bộ ngay khi kết nối lại.',false),
('vi','landing','feat4Title','GraceCounsel AI',false),
('vi','landing','feat4Desc','Một người bạn đồng hành thuộc linh AI được hỗ trợ bởi OpenAI — sự hướng dẫn dựa trên đức tin, sự thông hiểu Kinh Thánh và suy ngẫm cầu nguyện vào bất cứ lúc nào.',false),
('vi','landing','feat5Title','Kênh trực tiếp & Cuộc họp',false),
('vi','landing','feat5Desc','Tổ chức các buổi cầu nguyện trực tiếp, học Kinh Thánh và các cuộc họp tương tác. Lên lịch các buổi định kỳ và ghi lại để xem lại.',false),
('vi','landing','feat6Title','Cộng đồng cầu nguyện',false),
('vi','landing','feat6Desc','Tham gia các thử thách cầu nguyện, duy trì chuỗi ngày, chia sẻ trên bức tường cầu nguyện cộng đồng và cùng nhau giữ trách nhiệm trong đức tin.',false),
('vi','landing','feat7Title','Công cụ phát sóng mục vụ',false),
('vi','landing','feat7Desc','Gửi phát sóng qua WhatsApp, email và thông báo đẩy đến hội chúng của bạn. Mẫu đã được phê duyệt, quản lý người đăng ký và phân tích.',false),
('vi','landing','feat8Title','Tiếp cận nhà tư vấn',false),
('vi','landing','feat8Desc','Đặt các buổi tư vấn riêng với các nhà tư vấn Cơ Đốc đã được xác minh. Buổi video kèm lời nhắc, ghi chú và chăm sóc theo dõi.',false),
('vi','landing','feat9Title','Lời nhắc & Cảnh báo qua WhatsApp',false),
('vi','landing','feat9Desc','Nhận các bài tĩnh nguyện hằng ngày, lời nhắc cầu nguyện, nhắc nhở chuỗi ngày và thông báo trực tiếp trên WhatsApp. Chọn chính xác những gì bạn muốn và hủy bất cứ lúc nào.',false),
('vi','landing','splitEyebrow','Hai đối tượng, một nền tảng',false),
('vi','landing','splitTitle','Xây dựng cho tín hữu. Mở rộng cho mục vụ.',false),
('vi','landing','forIndividuals','Dành cho cá nhân',false),
('vi','landing','indivTitle','Nơi thánh riêng tư cho sự tăng trưởng thuộc linh của bạn',false),
('vi','landing','indivDesc','Dù bạn là tín hữu mới hay môn đồ dày dạn, ReKindle cho bạn cấu trúc và cộng đồng để đào sâu bước đi với Chúa mỗi ngày.',false),
('vi','landing','indiv1','Thư viện tĩnh nguyện hằng ngày với quyền truy cập không giới hạn',false),
('vi','landing','indiv2','Tĩnh nguyện bằng âm thanh — nghe mọi nơi, rảnh tay',false),
('vi','landing','indiv3','Truy cập ngoại tuyến — tải và đọc không cần tín hiệu',false),
