('vi','landing','indiv6','Học thuộc Kinh Thánh & kế hoạch đọc Kinh Thánh',false),
('vi','landing','indiv7','Đặt lịch với nhà tư vấn Cơ Đốc bất cứ lúc nào',false),
('vi','landing','indiv8','Lời nhắc qua WhatsApp cho tĩnh nguyện & cầu nguyện',false),
