('vi','landing','minTitle','Mọi thứ mục vụ của bạn cần để tiếp cận và môn đồ hóa',false),
('vi','landing','minDesc','Trao cho hội thánh hay mục vụ của bạn hạ tầng để giao tiếp ở quy mô lớn, tổ chức sự kiện trực tiếp và môn đồ hóa hội chúng.',false),
